drawDodge=function(c,g){const a=g.alt,m=g.map;miniBackdrop(c,g);for(const o of a.objects){if(o.kind==='warning'){const active=o.age>1.15;c.fillStyle=active?'#ed906d66':'#e9a67b15';c.strokeStyle=active?'#ffd6a4':'#edb06c';c.lineWidth=2;c.beginPath();c.arc(o.x,o.y,o.r,0,7);c.fill();c.stroke();c.setLineDash([5,8]);c.beginPath();c.arc(o.x,o.y,o.r-6,0,7);c.stroke();c.setLineDash([]);artLine(c,[[o.x-8,o.y],[o.x+8,o.y]],'#ffdeaa',2);artLine(c,[[o.x,o.y-8],[o.x,o.y+8]],'#ffdeaa',2);if(active)artGlow(c,o.x,o.y,o.r,'#f4a47966')}else{artLine(c,[[o.x-o.dx*.3,o.y-o.dy*.3],[o.x,o.y]],'#f6b87922',24);artLine(c,[[o.x-o.dx*.15,o.y-o.dy*.15],[o.x,o.y]],'#edab7466',9);artRock(c,o.x,o.y,20,{...m,stone:'#746a61',top:'#c6a781'},17);ellipse(c,o.x-3,o.y-4,4,3,'#ffc98d')}}for(const b of a.beams||[]){c.fillStyle=b.age>1.4?'#ed896e77':'#ed896e17';c.strokeStyle='#f3bd76aa';c.lineWidth=2;if(b.vertical){c.fillRect(b.pos-20,60,40,550);c.strokeRect(b.pos-20,60,40,550)}else{c.fillRect(40,b.pos-20,920,40);c.strokeRect(40,b.pos-20,920,40)}}for(const p of a.collectibles||[])miniGem(c,p.x,p.y,m.accent,18);miniPet(c,g,g.x,g.y,75)};
function artShip(c,x,y,m,t,enemy=false,boss=false){c.save();c.translate(x,y);if(enemy)c.rotate(Math.PI);const scale=boss?1.8:1;c.scale(scale,scale);artGlow(c,0,50,34,enemy?'#ffa16f44':m.accent+'44');for(const dx of [-17,17]){const length=15+Math.sin(t*19+dx)*7;artPoly(c,[[dx-5,32],[dx,53+length],[dx+5,32]],enemy?'#e9ab78aa':'#7be2f4aa');artPoly(c,[[dx-2,32],[dx,43+length*.5],[dx+2,32]],'#e8ffff')}artPoly(c,[[0,-47],[18,-10],[43,26],[31,34],[9,21],[0,40],[-9,21],[-31,34],[-43,26],[-18,-10]],m.edge);artPoly(c,[[0,-44],[14,-8],[38,25],[11,14],[0,29],[-11,14],[-38,25],[-14,-8]],enemy?'#9f7e78':m.top,m.edge,2);artPoly(c,[[0,-44],[0,29],[-11,14],[-38,25],[-14,-8]],enemy?'#655f6c':m.stone);artPoly(c,[[-7,-16],[0,-28],[7,-16],[6,9],[-6,9]],'#133c59',m.accent,1);for(const dx of [-28,28])roundRect(c,dx-3,10,6,25,2,m.stone,m.accent);artLine(c,[[-25,17],[-14,4]],'#e6f5f266',1);artLine(c,[[25,17],[14,4]],'#e6f5f266',1);c.restore()}
