function buildMazeArt(g){const a=g.alt,m=g.map,canvas=document.createElement('canvas');canvas.width=1000;canvas.height=650;const c=canvas.getContext('2d');artBlock(c,a.ox-13,a.oy-9,a.cols*a.cell+26,a.rows*a.cell+18,m,13);const floor=c.createLinearGradient(a.ox,a.oy,a.ox+900,a.oy+500);floor.addColorStop(0,m.terrain==='water'?'#3a8f9b':'#53685c');floor.addColorStop(1,m.terrain==='water'?'#165377':'#293e3e');c.fillStyle=floor;c.fillRect(a.ox,a.oy,a.cols*a.cell,a.rows*a.cell);for(let i=0;i<a.cells.length;i++){const x=a.ox+i%a.cols*a.cell,y=a.oy+Math.floor(i/a.cols)*a.cell;c.strokeStyle='#d1e1cc12';c.lineWidth=1;c.strokeRect(x+2,y+2,a.cell-4,a.cell-4);if(i%5===0)artLine(c,[[x+7,y+8],[x+13,y+11],[x+10,y+17]],'#142b3344',1)}const walls=[...a.mazeWalls].sort((p,q)=>p.y-q.y);for(const r of walls){c.fillStyle='#04182655';c.fillRect(r.x+5,r.y+6,r.w+2,r.h+4);c.fillStyle=m.edge;c.fillRect(r.x,r.y,r.w,r.h+6);c.fillStyle=m.stone;c.fillRect(r.x,r.y-4,r.w,r.h+4);c.fillStyle=m.top;c.fillRect(r.x,r.y-4,r.w,Math.min(3,r.h));if(r.w>20)for(let x=r.x+22;x<r.x+r.w;x+=33)artLine(c,[[x,r.y-2],[x,r.y+3]],m.edge+'66',1)}return canvas}
drawMaze=function(c,g){const a=g.alt,m=g.map;miniBackdrop(c,g);let cached=artMazeCache.get(a);if(!cached||cached.walls!==a.mazeWalls){cached={walls:a.mazeWalls,canvas:buildMazeArt(g)};artMazeCache.set(a,cached)}c.drawImage(cached.canvas,0,0);for(const r of a.relics)if(!r.found){const p=mazePoint(a,r.index);miniGem(c,p.x,p.y+Math.sin((g.elapsed||0)*3+r.index)*2,m.accent,Math.min(12,a.cell*.23))}const exit=mazePoint(a,a.exit);c.strokeStyle=a.progress===3?m.accent:'#a8b9ac55';c.lineWidth=3;c.beginPath();c.ellipse(exit.x,exit.y,a.cell*.3,a.cell*.25,0,0,7);c.stroke();if(a.hint>0){const r=a.relics.find(p=>!p.found),p=mazePoint(a,r?r.index:a.exit);c.setLineDash([3,5]);c.strokeStyle='#e8da9a';c.lineWidth=2;c.beginPath();c.arc(p.x,p.y,a.cell*.35,0,7);c.stroke();c.setLineDash([])}const w=mazePoint(a,a.wardenIndex??a.exit);if(['dinosaur','zombie'].includes(m.terrain))worldCreature(c,w.x,w.y+Math.sin(a.clock*3)*.8,m.terrain,Math.min(.58,a.cell/100));else artDrone(c,w.x,w.y,a.clock,m,Math.min(.6,a.cell/85));miniPet(c,g,g.x,g.y+15,Math.min(49,a.cell*.95))};
function artGlyph(c,x,y,index,size,colour){c.save();c.translate(x,y);c.strokeStyle=colour;c.fillStyle=colour;c.lineWidth=2.5;const type=index%8,outer=Math.floor(index/8);if(outer){c.beginPath();c.arc(0,0,size*.9,0,7);c.stroke()}if(type===0)artPoly(c,[[0,-size*.7],[size*.5,0],[0,size*.7],[-size*.5,0]],null,colour,3);if(type===1){c.beginPath();c.arc(0,0,size*.52,0,7);c.stroke();artLine(c,[[-size*.8,0],[size*.8,0]],colour,2)}if(type===2){artPoly(c,[[0,-size*.7],[size*.66,size*.5],[-size*.66,size*.5]],null,colour,3);artLine(c,[[0,-size*.4],[0,size*.1]],colour,2)}if(type===3){for(let i=0;i<3;i++)artLine(c,[[-size*.6,-size*.45+i*size*.45],[size*.6,-size*.45+i*size*.45]],colour,3)}if(type===4){c.strokeRect(-size*.5,-size*.5,size,size);artLine(c,[[-size*.5,-size*.5],[size*.5,size*.5]],colour,2)}if(type===5){for(let i=0;i<6;i++){const a=i*Math.PI/3;artLine(c,[[Math.cos(a)*size*.3,Math.sin(a)*size*.3],[Math.cos(a)*size*.7,Math.sin(a)*size*.7]],colour,3)}ellipse(c,0,0,3,3,colour)}if(type===6){artLine(c,[[-size*.65,size*.55],[-size*.25,-size*.5],[size*.15,size*.5],[size*.65,-size*.5]],colour,3)}if(type===7){c.beginPath();c.arc(0,0,size*.6,-2,2);c.stroke();ellipse(c,0,0,4,4,colour)}c.restore()}
drawMemory=function(c,g){const a=g.alt,m=g.map;miniBackdrop(c,g,true);for(const card of a.cards){const r=memoryRect(g,card.index),show=card.matched||a.preview>0||a.flipped.includes(card.index);roundRect(c,r.x+3,r.y+7,r.w,r.h,7,'#04101eaa');const grad=c.createLinearGradient(r.x,r.y,r.x+r.w,r.y+r.h);grad.addColorStop(0,card.matched?'#40796f':show?m.top:'#355267');grad.addColorStop(1,card.matched?'#183c42':show?m.stone:'#162b42');roundRect(c,r.x,r.y,r.w,r.h,7,grad,card.matched?m.accent:'#7593a388');roundRect(c,r.x+6,r.y+6,r.w-12,r.h-12,3,null,show?'#e6f6e855':'#607f8c44');for(const[dx,dy]of [[10,10],[r.w-10,10],[10,r.h-10],[r.w-10,r.h-10]])ellipse(c,r.x+dx,r.y+dy,1.5,1.5,'#ccded9aa');artGlyph(c,r.x+r.w/2,r.y+r.h/2,show?card.symbol:15,Math.min(26,r.w*.26),show?(card.matched?m.accent:'#172f3f'):'#668391');if(card.matched){c.fillStyle=m.accent;c.font='800 9px system-ui';c.textAlign='center';c.fillText('LINKED',r.x+r.w/2,r.y+r.h-12)}}c.fillStyle='#d2e8eb';c.font='700 13px system-ui';c.textAlign='center';c.fillText(a.preview>0?'SCAN THE RELIC PATTERNS':'ECHO VAULT · RESTORE THE PAIRS',500,55);miniPet(c,g,100,611,63)};
paintField=function(g){const canvas=document.createElement('canvas');canvas.width=g.w;canvas.height=g.h;const c=canvas.getContext('2d'),m=g.map;c.save();c.scale(g.w/1000,g.h/650);miniBackdrop(c,{...g,elapsed:0},false);const path=c.createLinearGradient(0,0,1000,650);path.addColorStop(0,m.path+'66');path.addColorStop(1,m.edge+'33');c.strokeStyle=path;c.lineWidth=105;artLine(c,[[60,325],[500,320],[940,325]],path,105);artLine(c,[[500,65],[500,585]],path,105);for(let i=0;i<6;i++){c.strokeStyle=m.top+'22';c.lineWidth=1;c.strokeRect(408+i*8,247+i*8,184-i*16,146-i*16)}c.strokeStyle=m.accent+'55';c.lineWidth=2;c.beginPath();c.ellipse(500,325,83,60,0,0,7);c.stroke();artGlyph(c,500,325,4,28,m.accent+'88');for(const[x,y]of [[62,173],[918,500],[60,500],[920,145]]){artBlock(c,x,y,26,65,m,10);for(let n=0;n<4;n++)roundRect(c,x+6,y+7+n*12,14,3,1,m.accent+'99')}c.restore();for(const r of g.walls){if(r.water){roundRect(c,r.x-4,r.y-4,r.w+8,r.h+8,5,m.top);roundRect(c,r.x,r.y,r.w,r.h,4,m.water);for(let y=r.y+12;y<r.y+r.h;y+=21)artLine(c,[[r.x+8,y],[r.x+r.w-8,y]],m.accent+'44',2)}else artBlock(c,r.x,r.y,r.w,r.h,m,12)}c.strokeStyle=m.edge;c.lineWidth=17;c.strokeRect(14,16,g.w-28,g.h-32);return canvas};
