worldCreature=function(c,x,y,type,size=1){c.save();c.translate(x,y);c.scale(size,size);ellipse(c,4,24,32,10,'#09223266');if(type==='dinosaur'){artPoly(c,[[-45,9],[-29,5],[-18,-11],[6,-20],[13,-37],[33,-40],[43,-24],[32,-11],[14,-9],[18,16],[6,28],[-7,25],[-12,10],[-26,18]],'#72935c','#253f35',2);artPoly(c,[[-16,-7],[7,-14],[15,-9],[13,11],[-4,12]],'#9dab74');artLine(c,[[5,11],[9,26],[21,26]],'#354e39',8);artLine(c,[[-10,11],[-15,23],[-3,23]],'#354e39',7);artLine(c,[[13,-19],[7,-9],[15,-6]],'#436a43',4);for(let i=0;i<5;i++)artLine(c,[[-20+i*8,1],[-17+i*8,-4]],'#355c3d',2);ellipse(c,32,-30,2.5,2,'#e5d58d');ellipse(c,33,-30,1,1,'#122e31');artLine(c,[[31,-18],[40,-21]],'#273a30',2)}else{artBlock(c,-20,-10,40,39,{...ART_WORLDS.zombie,top:'#6e8071'},7);artPoly(c,[[-16,-13],[-19,-32],[-6,-43],[14,-40],[22,-24],[13,-10]],'#789477','#283b34',2);artLine(c,[[-12,-26],[15,-26]],'#253a36',7);artLine(c,[[-9,-26],[2,-26]],'#d6df9b',2);artLine(c,[[7,-26],[14,-26]],'#d6df9b',2);artLine(c,[[-12,8],[-27,16],[-29,28]],'#677968',9);artLine(c,[[17,7],[28,12],[29,26]],'#677968',9);artLine(c,[[-9,23],[-12,40]],'#293b3b',11);artLine(c,[[11,23],[16,38]],'#293b3b',11);artLine(c,[[-9,5],[9,19]],'#a49a6a',5)}c.restore()};
renderBoss=function(c,e,g){const m=g.map,col=e.phase===2?'#e7ac78':m.accent;c.save();c.translate(e.x,e.y);ellipse(c,6,37,57,20,'#04162599');artPoly(c,[[-45,-20],[-26,-46],[25,-46],[46,-21],[42,29],[20,45],[-23,45],[-44,25]],m.edge,'#7b969d',3);artPoly(c,[[-35,-18],[-22,-35],[20,-35],[35,-18],[30,22],[0,35],[-31,20]],m.stone);artPoly(c,[[-28,-19],[0,-32],[28,-19],[0,-6]],m.top);roundRect(c,-27,-14,54,17,5,m.edge,col);artLine(c,[[-18,-6],[18,-6]],col,4);for(const dx of [-49,49]){artBlock(c,dx-12,-4,24,42,m,8);roundRect(c,dx-6,-17,12,29,3,m.edge,col);if(e.fire<.5)artGlow(c,dx,-19,19,col+'66')}for(let i=0;i<3;i++)artLine(c,[[-18+i*18,12],[-18+i*18,24]],m.edge,4);c.strokeStyle=col+'77';c.lineWidth=2;c.setLineDash([8,9]);c.beginPath();c.arc(0,0,59+(e.fire<.5?Math.sin((g.elapsed||0)*14)*4:0),0,7);c.stroke();c.setLineDash([]);c.restore()};
drawBot=function(c,e,g){if(e.type==='boss'){renderBoss(c,e,g);return}c.save();if(e.spawnShield>0)c.globalAlpha=.55;if(['dinosaur','zombie'].includes(g.map.terrain))worldCreature(c,e.x,e.y,g.map.terrain,e.type==='tank'?.95:.76);else{if(e.type==='tank')for(const dx of [-27,27]){roundRect(c,e.x+dx-7,e.y-14,14,42,4,g.map.edge,g.map.top);for(let n=0;n<4;n++)artLine(c,[[e.x+dx-5,e.y-8+n*8],[e.x+dx+5,e.y-8+n*8]],g.map.stone,2)}artDrone(c,e.x,e.y,g.elapsed,g.map,e.type==='tank'?1.12:.88)}if(e.fire<.35){c.strokeStyle='#edbc7888';c.lineWidth=2;c.beginPath();c.ellipse(e.x,e.y+20,e.r+7,11,0,0,7);c.stroke()}roundRect(c,e.x-23,e.y-48,46,4,2,'#102332');roundRect(c,e.x-23,e.y-48,46*Math.max(0,e.hp/Math.max(1,e.maxHp)),4,2,g.map.accent);c.restore()};
const artOldRender=renderArena;renderArena=function(g){artOldRender(g);if(g.alt)return;const c=g.ctx;for(const shot of g.bullets||[]){artLine(c,[[shot.x-shot.dx*.012,shot.y-shot.dy*.012],[shot.x,shot.y]],'#e2fff588',2)}if(g.shieldCharge>0)artGlow(c,g.x,g.y,52,'#71dbe419');if(g.map.terrain==='water')for(let i=0;i<10;i++){const x=(i*197)%g.w,y=g.h-((i*83+g.elapsed*15)%(g.h+20));c.strokeStyle='#b5f4ed44';c.lineWidth=1;c.beginPath();c.arc(x,y,2+i%3,0,7);c.stroke()}};
if(!game&&!window.location.hash.startsWith('#room=')&&!window.location.hash.startsWith('#challenge='))navigate('home');
